\begin{equation*}
	\tag{P}\label{eq:P}
	\minimize_{x\in\R^n}\varphi(x)\coloneqq f(x)+g(x)
\quad
	\stt x\in\closure C,
\end{equation*}

where \(C\) is a nonempty open and convex set with closure \(\closure C\),  \(\func{f}{\R^n}{\Rinf\coloneqq\R\cup\set{\pm\infty}}\) is differentiable on $\inte\dom f\neq\emptyset$, and \(\func{g}{\R^n}{\Rinf}\) is proper and lower semicontinuous (lsc).
For notational brevity, we define \(\cost\coloneqq\varphi+\indicator_{\closure C}\) with \(\indicator_X\) denoting the indicator function of set \(X\subseteq\R^n\), namely such that \(\indicator_X(x)=0\) if \(x\in X\) and \(\infty\) otherwise.


			Throughout, we fix a Legendre kernel \(\func{h}{\R^n}{\Rinf}\) with \(\dom\nabla h=\interior\dom h=C\),
namely, a proper, lsc, and strictly convex function  that is 1-coercive and \DEF{essentially smooth}, \ie such that \(\|\nabla h(x_k)\|\to\infty\) for every sequence \(\seq{x_k}\subset C\) converging to a boundary point of \(C\).
We will consider the following iterative scheme for addressing problem \eqref{eq:P},
where \(\func{\D}{\R^n\times\R^n}{\Rinf}\) denotes the \DEF{Bregman distance} induced by \(h\), defined as
\begin{equation}\label{eq:D}
	\D(x,y)
{}\coloneqq{}
	\begin{ifcases}
		h(x)-h(y)-\innprod{\nabla h(y)}{x-y} & y\in C,
	\\
		\infty\otherwise.
	\end{ifcases}
\end{equation}

\begin{algorithm}
	\caption{Mirror inertial forward-reflected-backward (\protect\BiFRB)}%
	\label{alg:BiFRB}%
	\begin{algorithmic}[1]%
\setlength{\itemsep}{1ex}%
\item[%
	Choose \(x^{-1},x^0\in C\),~
	inertial parameter \(\beta\in\R\),~ and
	stepsize \(\gamma>0\)%
]%
\item[%
	Iterate for \(k=0,1,\ldots\) until a termination criterion is met (cf. \cref{thm:termination})
]%
\State\label{state:BiFRB:y}%
	Set \(y^k\) such that
	\(
		\nabla h(y^k)
	{}={}
		\nabla h(x^k)-\gamma\bigl(\nabla f(x^k)-\nabla f(x^{k-1})\bigr)
	\)%
\State\label{state:BiFRB:x}%
	Choose
	\(
	\ifsiam
		\mathtight
	\fi
		x^{k+1}
	{}\in{}
		\argmin\limits_{w\in\R^n}\set{
			g(w)
			{}+{}
			\innprod*{w}{\nabla f(x^k)-\tfrac\beta\gamma\bigl(\nabla h(x^k)-\nabla h(x^{k-1})\bigr)}
			{}+{}
			\tfrac1\gamma\D(w,y^k)
		}
	\)%
\end{algorithmic}

\end{algorithm}

\begin{assumption}\label{ass:basic}%
	The following hold in problem \eqref{eq:P}:
	\begin{enumeratass}
	\item\label{ass:f}%
		\(\func{f}{\R^n}{\Rinf}\) is smooth relative to \(h\) (see \cref{sec:relsmooth}).
	\item\label{ass:g}%
		\(\func{g}{\R^n}{\Rinf}\) is proper and lsc.
	\item\label{ass:phi}%
		\(\inf\cost>-\infty\).
	\item\label{ass:T}%
		For any \(v\in\R^n\) and \(\gamma>0\), \(\argmin\set{\gamma g+h-\innprod{v}{\cdot}}\subseteq C\).
	\end{enumeratass}
\end{assumption}

			The extended-real line is denoted by \(\Rinf\coloneqq\R\cup\set{\pm\infty}\).
The positive and negative part of \(r\in\R\) are respectively defined as \([r]_+\coloneqq\max\set{0,r}\) and \([r]_-\coloneqq\max\set{0,-r}\), so that \(r=[r]_+-[r]_-\).

The distance of a point \(x\in\R^n\) to a nonempty set \(S\subseteq\R^n\) is given by \(\dist(x,S)=\inf_{z\in S} \|z-x\|\).
The interior, closure, and boundary of \(S\) are respectively denoted as \(\interior S\), \(\overline S\), and \(\boundary S=\overline S\setminus\interior S\).
The \DEF{indicator function} of \(S\) is \(\func{\indicator_S}{\R^n}{\Rinf}\) defined as \(\indicator_S(x)=0\) if \(x\in S\) and \(\infty\) otherwise.

A function \(\func{f}{\R^n}{\Rinf}\) is \DEF{proper} if \(f\not\equiv\infty\) and \(f>-\infty\), in which case its \DEF{domain} is defined as the set \(\dom f\coloneqq\set{x\in\R^n}[f(x)<\infty]\).
For \(\alpha\in\R\), \([f\leq\alpha]\coloneqq\set{x\in\R^n}[f(x)\leq\alpha]\) denotes the \(\alpha\)-sublevel set of \(f\);
	\([\alpha\leq f\leq\beta]\) with \(\alpha,\beta\in\R\) is defined accordingly. We say that \(f\) is \DEF{level bounded} (or \DEF{coercive}) if \(\liminf_{\|x\|\to\infty}f(x)=\infty\), and \(1\)-coercive if
\(\lim_{\|x\|\to\infty}f(x)/\|x\|=\infty\).


Given \(x\in\dom f\), \(\partial f(x)\) denotes the \DEF{Mordukhovich (limiting) subdifferential} of \(f\) at \(x\), given by
\[
	\partial f(x)
{}\coloneqq{}
	\set{v\in\R^n}[
		\exists\seq{x^k,v^k}~\text{s.t.}~ x^k\to x,~f(x^k)\to f(x),~
		\hat\partial f(x^k)\ni v^k\to v
	],
\]
and \(\hat\partial f(x)\) is the set of \DEF{regular subgradients} of \(f\) at \(x\), namely vectors \(v\in\R^n\) such that
\(
	\liminf_{\limsubstack{z&\to&x\\z&\neq&x}}{
		\frac{
			f(z)-f(x)-\innprod{v}{z-x}
		}{
			\|z-x\|
		}
	}
{}\geq{}
	0
\);
see, e.g.,~\cite{rockafellar2011variational,mordukhovich2018variational}.
\(\C^k(\mathcal U)\) is the set of functions \(\mathcal U\to\R\) which are \(k\) times continuously differentiable.
We write \(\C^k\) if \(\mathcal U\) is clear from context.
The notation \(\ffunc{T}{\R^n}{\R^n}\) indicates a set-valued mapping, whose \DEF{domain} and \DEF{graph} are respectively defined as
\(
	\dom T=\set{x\in\R^n}[T(x)\neq\emptyset]
\)
and
\(
	\graph T=\set{(x,y)\in\R^n\times\R^n}[y\in T(x)]
\).


			In the following definition, as well as throughout the entire paper, we follow the ex\-tend\-ed-real convention \(\infty-\infty=\infty\) to resolve possible ill definitions of difference of extended-real--valued functions.
Similarly, we will adopt the convention that \(\nicefrac10=\infty\).


\begin{definition}[relative smoothness]\label{def:relsmooth}%
	We say that an lsc function \(\func{f}{\R^n}{\Rinf}\) is smooth relative to \(h\) if \(\dom f\supseteq\dom h\) and there exists a constant \(L_{f,h}\geq0\) such that \(L_{f,h}h\pm f\) are convex functions  on \(\inte\dom h\).
	We may alternatively say that \(f\) is \(L_{f,h}\)-smooth relative to \(h\) to make the smoothness modulus \(L_{f,h}\) explicit.
\end{definition}

\begin{definition}[relative weak convexity]\label{def:relweak}%
	We say that an lsc function \(\func{f}{\R^n}{\Rinf}\) is weakly convex relative to \(h\) if there exists a (possibly negative) constant \(\sigma_{f,h}\in\R\) such that \(f-\sigma_{f,h}h\) is a convex function.
	We may alternatively say that \(f\) is \(\sigma_{f,h}\)-weakly convex relative to \(h\) to make the weak convexity modulus \(\sigma_{f,h}\) explicit.
\end{definition}

Note that relative smoothness of \(f\) is equivalent to the relative weak convexity of \(\pm f\).
Indeed, if \(f\) is \(L_{f,h}\)-smooth relative to \(h\), then both \(f\) and \(-f\) are \((-L_{f,h})\)-weakly convex.
Conversely, if \(f\) and \(-f\) are \(\sigma_{f,h}\)- and \(\sigma_{-f,h}\)-weakly convex relative to \(h\), respectively, then \(f\) (as well as \(-f\)) is \(L_{f,h}\)-smooth relative to \(h\) with
\begin{equation}\label{eq:Lf}
	L_{f,h}=\max\set{|\sigma_{f,h}|,|\sigma_{-f,h}|}.
\end{equation}
The relative weak convexity moduli \(\sigma_{\pm f,h}\) will be henceforth adopted when referring to \cref{ass:f}.
It will be convenient to \emph{normalize} these quantities into pure numbers
\begin{equation}\label{eq:pf}
	p_{\pm f,h}
{}\coloneqq{}
	\tfrac{\sigma_{\pm f,h}}{L_{f,h}}
{}\in{}
	[-1,1].
\end{equation}
To make all definitions and implications well posed, we will ignore the uninsteresting case in which \(f\) is affine, in which case \(L_{f,h}=0\) for any \(h\).


\begin{equation}
	\h\coloneqq\tfrac1\gamma h-f
\quad\text{and}\quad
	\f\coloneqq f-\tfrac\beta\gamma h,
\end{equation}

	We will also (ab)use the notation \(\D_\psi\) of the Bregman distance for functions \(\func{\psi}{\R^n}{\Rinf}\) differentiable on \(C\) that are not necessarily convex, thereby possibly having \(\D_\psi\not\geq0\).
	This notational abuse is justified by the fact that all algebraic identities of the Bregman distance used in the manuscript (e.g., the three-point identity \cite[Lem. 3.1]{chen1993convergence}) are valid regardless of whether \(\psi\) is convex or not, and will overall yield a major simplification of the math.


\begin{align}
	\label{eq:M-innprod}
		\M(w;x,x^-)
	{}={} &
		\varphi(w)
		{}+{}
		\D_{\h}(w,x)
		{}+{}
		\innprod*{w-x}{\nabla\f(x)-\nabla\f(x^-)}
	\\
	\label{eq:M-D}
	{}={} &
		\varphi(w)
		{}+{}
		\D_{\h-\f}(w,x)
		{}+{}
		\D_{\f}(w,x^-)
		{}-{}
		\D_{\f}(x,x^-),
	\end{align}

\begin{align}
		x^{k+1}
	{}\in{} &
		\T(x^k,x^{k-1}),
	\shortintertext{%
		where \(\ffunc{\T}{C\times C}{C}\) defined by
	}
	\label{eq:T}
		\T(x,x^-)
	{}\coloneqq{} &
		\argmin_{w\in\R^n}\M(w;x,x^-)
	\end{align}

\begin{definition}[\BiFRB-envelope]\label{def: envelope}%
	The envelope function associated to \BiFRB\ with stepsize \(\gamma<\nicefrac{1}{[\sigma_{f,h}]_-}\)  and inertia \(\beta\in\R\) is \(\func{\env}{C\times C}{\R}\) defined as
	\begin{equation}\label{eq:env}
		\env(x,x^-)
	{}\coloneqq{}
		\inf_{w\in\R^n}\M(w;x,x^-).
	\end{equation}
\end{definition}

	The convergence analysis in both cases revolves around the identification of a constant \(c>0\) determining a lower bounded merit function


\begin{equation}\label{eq:LL}
		\LL=\env+\tfrac{c}{2\gamma}\D+\D_\xi.
	\end{equation}

	The difference between the two cases is determined by function \(\xi\) appearing in the last Bregman operator \(\D_\xi\), having \(\xi=\f\) in the former case and \(\xi=L_{\f}\j\) in the latter, where \(L_{\f}\) is a Lipschitz constant for \(\nabla\f\) and


\begin{equation}\label{eq:j}
		\j\coloneqq\tfrac12\|{}\cdot{}\|^2
	\end{equation}

	is the squared Euclidean norm.


In what follows, patterning the normalization of \(\sigma_{\pm f,h}\) into \(p_{\pm f,h}\) detailed in \cref{sec:relsmooth} we also introduce the scaled stepsize
\begin{equation}
	\alpha\coloneqq\gamma L_{f,h},
\end{equation}

\begin{assumption}\label{ass:h}
	Function \(h\) has full domain, that is, \(C=\R^n\).
\end{assumption}

For $\eta\in(0,\infty]$, denote by $\Psi_\eta$ the class of functions $\psi:[0,\eta)\rightarrow\R_+$ satisfying the following: (i) $\psi(t)$ is right-continuous at $t=0$ with $\psi(0)=0$; (ii) $\psi$ is strictly increasing on $[0,\eta)$. 


\begin{definition}[{\cite[Def. 5]{wang2022exact}}]\label{def: GCKL}%
	Let $\func{f}{\R^n}{\Rinf}$ be proper and lsc.
	Let $\bar x\in\dom\partial f$ and $\mu\in\R$, and let $V\subseteq\dom\partial f$ be a nonempty subset.
	\begin{enumerate}
	\item
		We say that $f$ has the pointwise generalized concave Kurdyka-\L ojasiewicz~(KL) property at $\bar x\in\dom\partial f$, if there exist a neighborhood $U\ni\bar x$, $\eta\in(0,\infty]$ and a concave $\psi\in\Psi_\eta$, such that for all $x\in U\cap[0<f-f(\bar x)<\eta]$,
		\[
			\psi'_-\bigl(f(x)-f(\bar x)\bigr)\cdot\dist\bigl(0,\partial f(x)\bigr)\geq1,
		\]
		where $\psi_-'$ denotes the left derivative.
		Moreover, $f$ is a generalized concave KL function if it has the generalized concave KL property at every $x\in\dom\partial f$.
	\item
		Suppose that $f(x)=\mu$ on $V$.
		We say $f$ has the setwise\footnote{%
			We shall omit adjectives ``pointwise'' and ``setwise'' whenever there is no ambiguity.%
		}
		generalized concave KL property on $V$ if there exist $U\supset V$, $\eta\in(0,\infty]$ and a concave $\psi\in\Psi_\eta$ such that for every $x\in U\cap[0<f-\mu<\eta]$,
		\[
			\psi'_-\bigl(f(x)-\mu\bigr)\cdot\dist\bigl(0,\partial f(x)\bigr)\geq1.
		\]
	\end{enumerate}
\end{definition}

For a subset $\Omega\subseteq\R^n$, define $(\forall \varepsilon>0)$ $\Omega_\varepsilon=\set{x\in\R^n}[\dist(x,\Omega)<\varepsilon]$. 


In the remainder of the section, we will make use of the norm \(\norm*{{}\cdot{}}\) on the product space \(\R^n\times\R^n\) defined as \(\norm*{(x,y)}=\|x\|+\|y\|\).

