\begin{lemma}[relative prox-boundedness]\label{thm:proxbounded}%
	Suppose that \cref{ass:basic} holds.
	Then, the set \(\argmin\set{\gamma g+h+\innprod{v}{\cdot}}\) as in \cref{ass:T} is nonempty for any \(v\in\R^n\) and \(0<\gamma<\nicefrac{1}{[\sigma_{-f,h}]_-}\).
	In other words, \(g\) is prox bounded relative to \(h\) with threshold \(\gamma_{g,h}\geq\nicefrac{1}{[\sigma_{-f,h}]_-}\) \cite[Def. 2.3]{kan2012moreau}.
\end{lemma}

\begin{proof}
	Recall that a proper convex function admits affine minorant; see, e.g,~\cite[Cor. 16.18]{bauschke2017convex}.
	It then follows that \(\gamma g+h\) is 1-coercive by observing that
	\[
		\gamma g+h
	{}={}
		\gamma\cost-\gamma f+h
	{}={}
		\gamma\underbracket*{
			\vphantom{\left([\sigma_{-f,h}]_-\right)}
			\cost
		}_{\mathclap{\geq\inf\cost}}
		{}+{}
		\gamma\underbracket*{
			\left(-f+[\sigma_{-f,h}]_-h\right)
		}_{\text{convex}}
		{}+{}
		\underbracket*{
			\left(1-\gamma[\sigma_{-f,h}]_-\right)
		}_{>0}
		\overbracket*{
			\,h\,
		}^{\text{\clap{1-coercive}}}
	\]
	on \(\closure C\) and \(\infty\) on \(\R^n\setminus\closure C\).
\end{proof}

\begin{lemma}[{{\cite[Thm. 4.1]{ahookhosh2021bregman}}}]\label{thm:Legendre}%
	Suppose that \cref{ass:f} holds.
	Then, for every \(\gamma<\nicefrac{1}{[\sigma_{-f,h}]_-}\) the function \(\h\) is a Legendre kernel with \(\dom\h=\dom h\).
\end{lemma}

\begin{lemma}[basic properties of the model \(\M\) and the operator \(\T\)]\label{thm:basic}%
	Suppose that \cref{ass:basic} holds, and let \(\gamma<\nicefrac{1}{[\sigma_{-f,h}]_-}\) and \(\beta\in\R\) be fixed.
	The following hold:
	\begin{enumerate}
	\item \label{thm:M:eq}%
		\(
			\M(x;x,x^-)
		{}={}
			\cost(x)
		\)
		for all \(x,x^-\in C\).
	\item \label{thm:M:lb}%
		\(\M(w;x,x^-)\) is level bounded in \(w\) locally uniformly in \((x,x^-)\) on \(C\times C\).\footnote{%
			Namely, \(\bigcup_{(x,x^-)\in\mathcal V}\set{w\in\R^n}[\M(w;x,x^-)\leq\alpha]\) is bounded for any \(\mathcal V\subset C\times C\) compact and \(\alpha\in\R\).%
		}
	\item \label{thm:T:osc}%
		\(\T\) is locally bounded and osc,\footnote{%
			Being \(\T\) defined on \(C\times C\), osc and local boundedness are meant relative to \(C\times C\).
			Namely, \(\graph\T\) is closed relative to \(C\times C\times\R^n\), and \(\bigcup_{(x,x^-)\in\mathcal V}\T(x,x^-)\) is bounded for any \(\mathcal V\subset C\times C\) compact.%
		}
		and \(T(x,x^-)\) is a nonempty and compact subset of \(C\) for any \(x,x^-\in C\).
	\item \label{thm:T:partial}%
		\(\nabla\h(x)-\nabla\h(\bar x)-\nabla\f(x)+\nabla\f(x^-)\in\hat\partial\varphi(\bar x)\) for any \(x,x^-\in C\) and \(\bar x\in\T(x,x^-)\).
	\item \label{thm:T:fix}%
		If \(x\in\T(x,x)\), then \(0\in\hat\partial\varphi(x)\) and \(\def\stepsize{\gamma'}\T(x,x)=\set{x}\) for every \(\gamma'\in(0,\gamma)\).
	\end{enumerate}
	\begin{proof}
		We start by observing that \cref{thm:proxbounded} ensures that the set \(\T(x,x^-)\) is non\-empty for any \(x,x^-\in C\); this follows by considering the expression \eqref{eq:M-innprod} of the model, by observing that, for any \(x\in C\),
		\(
			\varphi+\D_{\h}({}\cdot{},x)
		{}={}
			g+\tfrac1\gamma h-\h(x)-\innprod*{\nabla\h(x)}{{}\cdot{}-x}
		\).
		For the same reason, it then follows from \cref{ass:T} that \(T(x,x^-)\subset C\).
		\begin{proofitemize}
		\item \ref{thm:M:eq}~
			Apparent, by considering \(w=x\) in \eqref{eq:M-D}.
		\item \ref{thm:M:lb} \& \ref{thm:T:osc}~
			The first assertion owes to the fact that \(\h\) is 1-coercive by \cref{thm:Legendre} and that both \(\h\) and \(\nabla\f\) are continuous on \(C\), so that for any compact \(\mathcal V\subset\R^n\times\R^n\) one has that
			\(
				\lim_{\|w\|\to\infty}\inf_{(x,x^-)\in\mathcal V}\M(w;x,x^-)=\infty
			\),
			as is apparent from \eqref{eq:M-innprod}.
			In turn, the second assertion follows from \cite[Thm. 1.17]{rockafellar2011variational}.
		\item \ref{thm:T:partial}~
			Follows from the optimality conditions of \(\bar x\in\argmin\M({}\cdot{};x,x^-)\), for \(\bar x\in C\) by assumption and thus the calculus rule of \cite[Ex. 8.8(c)]{rockafellar2011variational} applies (having \(\h\) smooth around \(\bar x\in C\)).
		\item \ref{thm:T:fix}~
			That \(0\in\hat\partial\varphi(x)\) follows from assertion \ref{thm:T:partial}, and the other claim from \cite[Lem. 3.6]{ahookhosh2021bregman} by observing that \(\T(x,x)=\argmin\set{\varphi+\D_{\h}({}\cdot{},x)}\) for any \(\gamma>0\) and \(\beta\in\R\).
		\qedhere
		\end{proofitemize}
	\end{proof}
\end{lemma}

\begin{lemma}[basic properties of \(\env\)]%
	Suppose that \cref{ass:basic} holds.
	Then, for any \(\gamma<\nicefrac{1}{[\sigma_{f,h}]_-}\) and \(\beta\in\R\) the following hold:
	\begin{enumerate}
	\item\label{thm:env:C0}%
		\(\env\) is (real-valued and) continuous on \(C\times C\); in fact, it is locally Lipschitz provided that \(f,h\in\C^2(C)\).
	\item\label{thm:env:eq}%
		For any \(x,x^-\in C\) and \(\bar x\in\T(x,x^-)\)
		\[
		\ifsiam
			\mathtight[0.45]
		\fi
			\env(x,x^-)
		{}={}
			\M(\bar x;x,x^-)
		{}={}
			\varphi(\bar x)
			{}+{}
			\D_{\h-\f}(\bar x,x)
			{}+{}
			\D_{\f}(\bar x,x^-)
			{}-{}
			\D_{\f}(x,x^-).
		\]
	\item\label{thm:env:leq}%
		\(
			\env(x,x^-)
		{}\leq{}
			\varphi(x)
		\)
		for any \(x,x^-\in C\).
	\end{enumerate}
	\begin{proof}~
		\begin{proofitemize}
		\item \ref{thm:env:C0}~
			In light of the uniform level boundedness asserted in \cref{thm:M:lb}, continuity of \(\env\) follows from $\text{\cite[Thm. 1.17(c)]{rockafellar2011variational}}$ by observing that the mapping \((x,x^-)\mapsto\M(w;x,x^-)\) is continuous for every \(w\);
			in fact, when \(f\) and \(h\) are both \(\C^2\) on \(C\), its gradient exists and is continuous with respect to all its arguments, which together with local boundedness of \(\T\), cf. \cref{thm:T:osc}, gives that \(-\env\) is a lower-\(\C^1\) function in the sense of \cite[Def. 10.29]{rockafellar2011variational}, and in particular locally Lipschitz continuous by virtue of \cite[Thm.s 10.31 and 9.2]{rockafellar2011variational}.
		\item \ref{thm:env:eq} \& \ref{thm:env:leq}~
			The identity follows by definition, cf. \eqref{eq:env} and \eqref{eq:T}.
			The inequality follows by considering \(w=x\) in \eqref{eq:env} and \eqref{eq:M-D}.
		\qedhere
		\end{proofitemize}
	\end{proof}
\end{lemma}

			We now work towards establishing a merit function for \BiFRB, starting from comparing the values of \(\env(\bar x,x)\) and \(\env(x,x^-)\), with \(\bar x\in\T(x,x^-)\).
Owing to \cref{thm:env:leq}, we have
\begin{align}
\nonumber
	\env(\bar x,x)
{}\leq{}
	\varphi(\bar x)
{}={} &
	\cost(\bar x)
\\
\label{eq:descent}
{}={} &
	\env(x,x^-)
	{}-{}
	\D_{\h-\f}(\bar x,x)
	{}-{}
	\overbracket*{
		\D_{\f}(\bar x,x^-)
	}
	{}+{}
	\D_{\f}(x,x^-).
\end{align}


\begin{theorem}\label{thm:SD}%
	Suppose that \cref{ass:basic} holds and consider one of the following scenarios:
	\begin{enumerator}
	\item\label{thm:SD:fconv}%
		either \(\f\) is convex (\ie, \(\alpha p_{f,h}-\beta\geq0\)) and
		\(
			\beta
		{}>{}
			-\nicefrac{(1+3\alpha p_{-f,h})}{2}
		\),
		in which case
		\[
			\xi\coloneqq\f
		\quad\text{and}\quad
				c
			{}\coloneqq{}
				1+2\beta+3\alpha p_{-f,h}>0,
		\]
	\item\label{thm:SD:fsmooth}%
		or \(\f\) is \(L_{\f}\)-Lipschitz differentiable, \(h\) is \(\sigma_h\)-strongly convex, and
		\[
			c
		{}\coloneqq{}
			(1+\alpha p_{-f,h})\sigma_h
			{}-{}
			2\gamma L_{\f}
		{}>{}
			0,
		\]
		in which case \(\xi\coloneqq L_{\f}\j\).
	\end{enumerator}
	Then, for \(\LL\) as in \eqref{eq:LL} the following assertions hold:
	\begin{enumerate}
	\item\label{thm:SD:leq}%
		\begin{subequations}
			For every \(x,x^-\in C\) and \(\bar x\in\T(x,x^-)\),
			\begin{align}
			\label{eq:SD}
				\LL(\bar x,x)
			{}\leq{} &
				\LL(x,x^-)
				{}-{}
				\tfrac{c}{2\gamma}\D(\bar x,x)
				{}-{}
				\tfrac{c}{2\gamma}\D(x,x^-)
			\shortintertext{and}
			\label{eq:L:geq}
				\cost(\bar x)
			{}\leq{} &
				\LL(x,x^-)
				{}-{}
				\tfrac{c}{\gamma}\D(\bar x,x)
				{}-{}
				\tfrac{c}{2\gamma}\D(x,x^-).
			\end{align}
		\end{subequations}
	\item\label{thm:SD:inf}%
		\(\inf\LL=\inf\cost\), and \(\LL\) is level bounded iff so is \(\cost\).
	\end{enumerate}
\end{theorem}

\begin{theorem}[function value convergence of \BiFRB]\label{thm:subseq}%
	Let $\seq{x^k}$ be a sequence generated by \BiFRB* in the setting of \cref{thm:SD}.
	Then,
	\begin{enumerate}
	\item\label{thm:subseq:SD}%
		It holds that
		\begin{equation}\label{SD inequality}
			\LL\left(x^{k+1},x^k\right)\leq\LL\left(x^k,x^{k-1}\right)-\tfrac{c}{2\gamma}\D\left(x^{k+1},x^k\right)-\tfrac{c}{2\gamma}\D\left(x^k,x^{k-1}\right).
		\end{equation}
		Then, $\sum_{k=0}^\infty \D\left(x^k,x^{k-1}\right)<\infty$ and $\LL(x^{k},x^{k-1})\to\varphi^\star$ as $k\to\infty$ for some $\varphi^\star\geq\inf\cost$.
	\item\label{thm:subseq:bounded}%
		If \(\cost\) is level bounded, then \(\seq{x^k}\) is bounded.
	\item\label{thm:subseq:omega}%
		Suppose that \cref{ass:h} holds, and let \(\omega\) be the set of limit points of \(\seq{x^k}\).
		Then, \(\varphi\) is constant on \(\omega\) with value \(\varphi^\star\), and for every \(x^\star\in\omega\) it holds that \(x^\star\in\T(x^\star,x^\star)\) and \(0\in\hat\partial\varphi(x^\star)\).
	\end{enumerate}
	\begin{proof}~
		\begin{proofitemize}
		\item\ref{thm:subseq:SD}~
			Recall from \cref{thm:SD} that \eqref{SD inequality} holds and that \(\inf\LL=\inf\cost>-\infty\), from which the convergence of \(\seq{\LL(x^{k},x^{k-1})}\) readily follows.
			In turn, a telescoping argument on \eqref{SD inequality} shows that \(\sum_{k\in\N}\D(x^k,x^{k-1})<\infty\).
		\item\ref{thm:subseq:bounded}~
			It follows from \cref{thm:subseq:SD} that \(\LL\left(x^{k+1},x^k\right)\leq\LL(x^0,x^{-1})\) holds for every \(k\).
			Then boundedness of \(\seq{x^k}\) is implied by level boundedness of \(\LL\); see \cref{thm:SD:inf}.
		\item\ref{thm:subseq:omega}~
			Suppose that a subsequence \(\seq{x^{k_j}}[j\in\N]\) converges to a point \(x^\star\), then so do \(\seq{x^{k_j\pm1}}\) by \cref{thm:subseq:SD} and \cite[Prop. 2.2(iii)]{bauschke2003iterating}.
			Since \(x^{k_j+1}\in\T(x^{k_j},x^{k_j-1})\), by passing to the limit osc of \(\T\) (\cref{thm:T:osc}) implies that \(x^\star\in\T(x^\star,x^\star)\).
			Invoking \cref{thm:T:fix} yields the stationarity condition \(0\in\hat\partial\varphi(x^\star)\).
			Moreover, by continuity of \(\LL\) one has
			\[
				\varphi^\star
			{}\defeq{}
				\lim_{k\to\infty}\LL\left(x^k,x^{k-1}\right)
			{}={}
				\LL(x^\star,x^\star)
			{}={}
				\varphi(x^\star),
			\]
			where the last equality follows from \cref{thm:env:eq}, owing to the inclusion \(x^\star\in\T(x^\star,x^\star)\) (and the fact that \(\D_\psi(x,x)=0\) for any differentiable function \(\psi\)).
			From the arbitrarity of \(x^\star\in\omega\) we conclude that \(\varphi\equiv\varphi^\star\) on \(\omega\).
		\qedhere
		\end{proofitemize}
	\end{proof}
\end{theorem}

\begin{lemma}[{{\cite[Lem. 4.4]{wang2022exact}}}]\label{lemma: Uniformize GCKL}%
	Let $\func{f}{\R^n}{\Rinf}$ be proper lsc and let $\mu\in\R$.
	Let $\Omega\subseteq\dom\partial f$ be a nonempty compact set on which $f(x)=\mu$ for all $x\in\Omega$.
	Then the following hold:
	\begin{enumerate}
	\item
		Suppose that $f$ satisfies the pointwise generalized concave KL property at each $x\in\Omega$.
		Then there exist $\varepsilon>0,\eta\in(0,\infty]$ and $\psi\in\Psi_\eta$ such that $f$ has the setwise generalized concave KL property on $\Omega$ with respect to $U=\Omega_\varepsilon$, $\eta$ and $\psi$.
	\item \label{uniformize exact modulus}%
		Set $U=\Omega_\varepsilon$ and define $h:(0,\eta)\rightarrow\R_+$ by
		\[
			h(s)=\sup\set{\dist^{-1}\left(0,\partial f(x)\right)}[{x\in U\cap[s\leq f-\mu<\eta]}].
		\]
		Then the function $\func{\tilde\psi}{[0,\eta)}{\R_+}$ defined by \((\forall 0<t<\eta)~\tilde\psi(t)=\int_0^th(s)ds\) with \(\tilde{\psi}(0)=0\) is well defined and belongs to $\Psi_\eta$.
		The function $f$ has the setwise generalized concave KL property on $\Omega$ with respect to $U$, $\eta$ and $\tilde\psi$.
		Moreover,
		\[
			\tilde{\psi}
		{}={}
			\inf\left\{
				\psi\in\Psi_\eta
				\,\Big|\,
				\text{\begin{tabular}{@{}c@{}}%
						\(\psi\) is a concave desingularizing function\\
						of $f$ on $\Omega$ with respect to $U$ and $\eta$
				\end{tabular}}
			\right\}.
		\]
	\end{enumerate}
	We say that $\tilde{\psi}$ is the exact modulus of the setwise generalized concave KL property of \(f\) on \(\Omega\) with respect to $U$ and $\eta$.
\end{lemma}

\begin{proof}
	Set \((\forall k\in\N)\) $\delta_{k}=\F(z^k)$ for simplicity.
	Then $\delta_k=\LL(x^k,x^{k-1})$, $\delta_{k}\to\varphi^\star$ decreasingly and $\dist(x^k,\omega)\to0$ as $k\to\infty$ by invoking \cref{thm:subseq}.
	Assume without loss of generality that \((\forall k\in\N)\) $\delta_{k}>\varphi^\star$, otherwise we would have $(\exists k_0\in\N)$ $x^{k_0}=x^{k_0+1}$ due to \cref{thm:subseq:SD}, from which the desired result readily follows by simple induction.
	Thus $(\exists k_0\in\N)$ $(\forall k\geq k_0)$ $z^k\in\Omega_r\cap[0<\F-\varphi^\star<\eta]$.
	Appealing to \cref{thm:subseq:omega} and \cref{thm:M:eq} yields that $\F$ is constantly equal to $\varphi^\star$ on the compact set $\omega(z^0)$.
	In turn, all conditions in \cref{uniformize exact modulus} are satisfied, which implies that for $k\geq k_0$
	\begin{equation}\label{formula: KL inequality of F}
		1\leq(\tilde\psi)'_-\left(\delta_{k}-\varphi^\star\right)\dist\left(0,\partial\F(z^k)\right).
	\end{equation}
	Define $(\forall k\in\N)$
	\begin{align*}
		u^k={}
	&
		\nabla^2\h(x^k)(x^k-x^{k+1})+\nabla^2\f(x^k)(x^{k+1}-x^k)+\tfrac{c}{2\gamma}\bigl(\nabla h(x^k)-\nabla h(x^{k-1})\bigr)
	\\
	&
		+\nabla\f(x^{k-1})-\nabla\f(x^k)+\nabla\xi(x^k)-\nabla\xi(x^{k-1}),
	\\
		v^k={}
	&
		\nabla^2\f(x^{k-1})(x^k-x^{k+1})+\tfrac{c}{2\gamma}\nabla^2h(x^{k-1})(x^{k-1}-x^k)+\nabla^2\xi(x^{k-1})(x^{k-1}-x^k).
	\end{align*}
	Then $\norm{u^k}\leq(M_1+M_2)\norm{x^{k+1}-x^k}+(M_1+(\nicefrac{c}{2\gamma})M_3+M_4)\norm{x^k-x^{k-1}}$ and $\norm{v^k}\leq M_1\norm{x^{k+1}-x^k}+((\nicefrac{c}{2\gamma})M_3+M_4)\norm{x^k-x^{k-1}}$, where $M_1=\sup\|\nabla^2\f(\mathcal{B})\|$, $M_2=\sup\|\nabla^2\h(\mathcal{B})\|$, $M_3=\sup\norm{\nabla^2h(\mathcal{B})}$, and $M_4=\sup\norm{\nabla^2\xi(\mathcal{B})}$.
	Applying subdifferential calculus to $\partial\F(z_k)$ yields that
	\[
		\partial\F(z^k)
	{}={}
		\bigl(\partial\varphi(x^{k+1})+\nabla\h(x^{k+1})-\nabla\h(x^k)+\nabla\f(x^{k})-\nabla \f(x^{k-1})\bigr)\times\{u^k\}\times\{v^k\},
	\]
	which together with \cref{thm:T:partial} entails that $(0,u^k,v^k)\in\partial\F(z^k)$.
	In turn, summing the aforementioned bounds on $\norm{u^k}$ and $\norm{v^k}$ gives
	\begin{equation}\label{subd F upper bound}
		\dist\left(0,\partial\F(z^k)\right)\leq M\norm*{(x^{k+1}-x^k,x^k-x^{k-1})},
	\end{equation}
	where $M=\max\set{2M_1+M_2,M_1+(\nicefrac{c}{\gamma})M_3+2M_4}$.

	Finally, we show that $\seq{x^k}$ is convergent.
	For simplicity, define $(\forall k,l\in\N)$ $\Delta_{k,l}=\tilde\psi\left(\delta_{k}-\varphi^\star\right)-\tilde\psi\left(\delta_{l}-\varphi^\star\right)$.
	Then, combining~\eqref{formula: KL inequality of F} and~\eqref{subd F upper bound} yields
	\begin{align*}
		1
	&{}\leq{}
		M(\tilde{\psi})'_-(\delta_{k}-\varphi^\star)\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}
		{}\leq{}
		\tfrac{M\Delta_{k,k+1}}{\delta_k-\delta_{k+1}}\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}
	\\
	&{}\leq{}
		\frac{2\gamma M\Delta_{k,k+1}}{c\left(\D(x^{k+1},x^k)+\D(x^k,x^{k-1})\right)}\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}
	\\
	&{}\leq{}
		\frac{2\gamma M\Delta_{k,k+1}\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}}{c \sigma\norm{x^{k+1}-x^k}^2+c \sigma\norm{x^k-x^{k-1}}^2}\leq \frac{4\gamma M\Delta_{k,k+1}}{c \sigma\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}},
	\end{align*}
	where the second inequality is implied by concavity of $\tilde\psi$, the third one follows from \eqref{SD inequality}, and the fourth one holds because $\sigma>0$ is the strong convexity modulus of $h$ on $\mathcal{B}$.
	Hence,
	\begin{equation}\label{consecutive gap}
		\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}\leq\tfrac{4\gamma M}{c\sigma}\Delta_{k,k+1}.
	\end{equation} 
	Summing~\eqref{consecutive gap} from $k=k_0$ to an arbitrary $l\geq k_0+1$ and passing $l$ to infinity justifies~\eqref{finite length}.
	A similar procedure shows that $\seq{x^k}$ is Cauchy, which together with \cref{thm:subseq:omega} entails the rest of the statement. 
\end{proof}

\begin{lemma}\label{thm:fconv:general}%
	Suppose that \cref{ass:basic} holds and let \(\gamma>0\) and \(\beta\in\R\) be such that \(\f\coloneqq f-\frac\beta\gamma h\) is a convex function.
	Then, for every \(x,x^-\in C\) and \(\bar x\in\T(x,x^-)\)
	\begin{align}\label{eq:decrease:fconv}
		\left(\env+\D_{\f}\right)(\bar x,x)
	{}\leq{} &
		\left(\env+\D_{\f}\right)(x,x^-)
		{}-{}
		\D_{\h-2\f}(\bar x,x).
% 	\shortintertext{%
% 		If \(\h-\f\) too is convex, then it also holds that
% 	}
% 		\varphi(\bar x)
% 	{}\leq{} &
% 		\left(\env+\D_{\f}\right)(x,x^-)
% 		{}-{}
% 		\D_{\h-2\f}(\bar x,x),
	\end{align}
	If \(\h-\f\) too is convex, then \(\env+\D_{\f}\) has the same infimum of \(\cost\), and is level bounded iff so is \(\cost\).%
	\begin{proof}
		All the claimed inequalities follows from \eqref{eq:descent} together with the fact that \(\D_{\f}\geq0\), and that \(\D_{\h-\f}\geq0\) too when \(\h-\f\) is convex.
