\begin{proof}
	Set \((\forall k\in\N)\) $\delta_{k}=\F(z^k)$ for simplicity.
	Then $\delta_k=\LL(x^k,x^{k-1})$, $\delta_{k}\to\varphi^\star$ decreasingly and $\dist(x^k,\omega)\to0$ as $k\to\infty$ by invoking \cref{thm:subseq}.
	Assume without loss of generality that \((\forall k\in\N)\) $\delta_{k}>\varphi^\star$, otherwise we would have $(\exists k_0\in\N)$ $x^{k_0}=x^{k_0+1}$ due to \cref{thm:subseq:SD}, from which the desired result readily follows by simple induction.
	Thus $(\exists k_0\in\N)$ $(\forall k\geq k_0)$ $z^k\in\Omega_r\cap[0<\F-\varphi^\star<\eta]$.
	Appealing to \cref{thm:subseq:omega} and \cref{thm:M:eq} yields that $\F$ is constantly equal to $\varphi^\star$ on the compact set $\omega(z^0)$.
	In turn, all conditions in \cref{uniformize exact modulus} are satisfied, which implies that for $k\geq k_0$
	\begin{equation}\label{formula: KL inequality of F}
		1\leq(\tilde\psi)'_-\left(\delta_{k}-\varphi^\star\right)\dist\left(0,\partial\F(z^k)\right).
	\end{equation}
	Define $(\forall k\in\N)$
	\begin{align*}
		u^k={}
	&
		\nabla^2\h(x^k)(x^k-x^{k+1})+\nabla^2\f(x^k)(x^{k+1}-x^k)+\tfrac{c}{2\gamma}\bigl(\nabla h(x^k)-\nabla h(x^{k-1})\bigr)
	\\
	&
		+\nabla\f(x^{k-1})-\nabla\f(x^k)+\nabla\xi(x^k)-\nabla\xi(x^{k-1}),
	\\
		v^k={}
	&
		\nabla^2\f(x^{k-1})(x^k-x^{k+1})+\tfrac{c}{2\gamma}\nabla^2h(x^{k-1})(x^{k-1}-x^k)+\nabla^2\xi(x^{k-1})(x^{k-1}-x^k).
	\end{align*}
	Then $\norm{u^k}\leq(M_1+M_2)\norm{x^{k+1}-x^k}+(M_1+(\nicefrac{c}{2\gamma})M_3+M_4)\norm{x^k-x^{k-1}}$ and $\norm{v^k}\leq M_1\norm{x^{k+1}-x^k}+((\nicefrac{c}{2\gamma})M_3+M_4)\norm{x^k-x^{k-1}}$, where $M_1=\sup\|\nabla^2\f(\mathcal{B})\|$, $M_2=\sup\|\nabla^2\h(\mathcal{B})\|$, $M_3=\sup\norm{\nabla^2h(\mathcal{B})}$, and $M_4=\sup\norm{\nabla^2\xi(\mathcal{B})}$.
	Applying subdifferential calculus to $\partial\F(z_k)$ yields that
	\[
		\partial\F(z^k)
	{}={}
		\bigl(\partial\varphi(x^{k+1})+\nabla\h(x^{k+1})-\nabla\h(x^k)+\nabla\f(x^{k})-\nabla \f(x^{k-1})\bigr)\times\{u^k\}\times\{v^k\},
	\]
	which together with \cref{thm:T:partial} entails that $(0,u^k,v^k)\in\partial\F(z^k)$.
	In turn, summing the aforementioned bounds on $\norm{u^k}$ and $\norm{v^k}$ gives
	\begin{equation}\label{subd F upper bound}
		\dist\left(0,\partial\F(z^k)\right)\leq M\norm*{(x^{k+1}-x^k,x^k-x^{k-1})},
	\end{equation}
	where $M=\max\set{2M_1+M_2,M_1+(\nicefrac{c}{\gamma})M_3+2M_4}$.

	Finally, we show that $\seq{x^k}$ is convergent.
	For simplicity, define $(\forall k,l\in\N)$ $\Delta_{k,l}=\tilde\psi\left(\delta_{k}-\varphi^\star\right)-\tilde\psi\left(\delta_{l}-\varphi^\star\right)$.
	Then, combining~\eqref{formula: KL inequality of F} and~\eqref{subd F upper bound} yields
	\begin{align*}
		1
	&{}\leq{}
		M(\tilde{\psi})'_-(\delta_{k}-\varphi^\star)\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}
		{}\leq{}
		\tfrac{M\Delta_{k,k+1}}{\delta_k-\delta_{k+1}}\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}
	\\
	&{}\leq{}
		\frac{2\gamma M\Delta_{k,k+1}}{c\left(\D(x^{k+1},x^k)+\D(x^k,x^{k-1})\right)}\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}
	\\
	&{}\leq{}
		\frac{2\gamma M\Delta_{k,k+1}\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}}{c \sigma\norm{x^{k+1}-x^k}^2+c \sigma\norm{x^k-x^{k-1}}^2}\leq \frac{4\gamma M\Delta_{k,k+1}}{c \sigma\norm*{(x^{k+1}-x^k,x^k-x^{k-1})}},
