\begin{lemma}\label{thm:fsmooth:general}%
	Additionally to \cref{ass:basic}, suppose that \(\f\) is \(L_{\f}\)-Lipschitz differentiable for some \(L_{\f}\geq0\).
	Then, for every \(x,x^-\in C\) and \(\bar x\in\T(x,x^-)\)
	\begin{equation}\label{eq:decrease:fsmooth}
		\left(\env+\D_{L_{\f}\j}\right)(\bar x,x)
	{}\leq{}
		\left(\env+\D_{L_{\f}\j}\right)(x,x^-)
		{}-{}
		\D_{\h-2L_{\f}\j}(\bar x,x).
	\end{equation}
	If \(\h-L_{\f}\j\) is a convex function, then \(\env+\D_{L_{\f}\j}\) has the same infimum of \(\cost\), and is level bounded iff so is \(\cost\).

\begin{proof}
		By means of the three-point identity, that is, by using \eqref{eq:M-innprod} in place of \eqref{eq:M-D}, inequality \eqref{eq:descent} can equivalently be written as
		\begin{align*}
			\env(\bar x,x)
		{}\leq{}
			\cost(\bar x)
		{}={} &
			\env(x,x^-)
			{}-{}
			\D_{\h}(\bar x,x)
			{}-{}
			\innprod*{\bar x-x}{\nabla\f(x)-\nabla\f(x^-)}
		\shortintertext{%
			which by using Young's inequality on the inner product and \(L_{\f}\)-Lipschitz differentiability yields
		}
		{}\leq{} &
			\env(x,x^-)
			{}-{}
			\D_{\h}(\bar x,x)
			{}+{}
			\tfrac{L_{\f}}{2}\|\bar x-x\|^2
			{}+{}
			\tfrac{L_{\f}}{2}\|x-x^-\|^2.
		\end{align*}
		Rearranging and using the fact that \(\D_{\j}(x,y)=\frac12\|x-y\|^2\) yields the claimed inequality.

		Under convexity of \(\h-L_{\f}\j\), we may draw the same conclusions as in the proof of \cref{thm:fconv:general} by observing that the same application of Young's inequality above, combined with the expression \eqref{eq:M-innprod} of \(\M\), gives
		\[
			\env(y,y^-)
		{}={}
			\M(\bar y;y,y^-)
		{}\geq{}
			\varphi(\bar y)
			{}+{}
			\D_{\h}(\bar y,y)
			{}-{}
			\tfrac{L_{\f}}{2}\|\bar y-y\|^2
			{}-{}
			\tfrac{L_{\f}}{2}\|y-y^-\|^2,
		\]
		holding for any \(y,y^-\in C\) and \(\bar y\in\T(y,y^-)\).
	\end{proof}

